refentry.refsect1:
&reftitle.description;
mixedfilter_var mixedvalue intfilterFILTER_DEFAULT arrayintoptions0
Функция фильтрует переменную фильтрами проверки — константами семейства FILTER_VALIDATE_*, очистки — семейства FILTER_SANITIZE_* — или пользовательскими фильтрами.

  &reftitle.examples;

   Пример фильтрации переменной функцией filter_var


<?php

var_dump(filter_var('bob@example.com', FILTER_VALIDATE_EMAIL));
var_dump(filter_var('https://example.com', FILTER_VALIDATE_URL, FILTER_FLAG_PATH_REQUIRED));


   &example.outputs;


string(15) "bob@example.com"
bool(false)




   Пример фильтрации массива


<?php

$emails = [
   "bob@example.com",
   "test@example.local",
   "invalidemail"
];

var_dump(filter_var($emails, FILTER_VALIDATE_EMAIL, FILTER_REQUIRE_ARRAY));


   &example.outputs;


array(3) {
 [0]=>
 string(15) "bob@example.com"
 [1]=>
 string(18) "test@example.local"
 [2]=>
 bool(false)
}




   Пример передачи массива в параметр options


<?php

$options = [
    'options' => [
        'min_range' => 10,
    ],
    'flags' => FILTER_FLAG_ALLOW_OCTAL,
];

var_dump(filter_var('0755', FILTER_VALIDATE_INT, $options));
var_dump(filter_var('011', FILTER_VALIDATE_INT, $options));


   &example.outputs;


int(493)
bool(false)




   Пример передачи флагов напрямую или с помощью массива (array)


<?php

$str = 'string';

var_dump(filter_var($str, FILTER_VALIDATE_BOOLEAN, FILTER_NULL_ON_FAILURE));
var_dump(filter_var($str, FILTER_VALIDATE_BOOLEAN, ['flags' => FILTER_NULL_ON_FAILURE]));


   &example.outputs;


NULL
NULL




   Пример корректной проверки результата валидации


<?php

$value = '0';

// Неправильно: 0 — допустимое целое число, но с оператором неравенства приводится к false
if (!filter_var($value, FILTER_VALIDATE_INT)) {
    echo "Неправильная проверка: значение '$value' отклонено\n";
}

// Правильно: строгое сравнение с false
if (filter_var($value, FILTER_VALIDATE_INT) === false) {
    echo "Значение '$value' не относится к допустимым целым числам\n";
} else {
    echo "Значение '$value' — допустимое целое число\n";
}


   &example.outputs;


Неправильная проверка: значение '0' отклонено
Значение '0' — допустимое целое число




   Пример проверки результата булевой валидации


<?php

foreach (['yes', 'no', 'maybe'] as $value) {
    $result = filter_var($value, FILTER_VALIDATE_BOOLEAN, FILTER_NULL_ON_FAILURE);

    // Значение false — допустимый результат, поэтому проверяется значение null
    if ($result === null) {
        echo "Значение '$value' не относится к допустимым логическим значениям\n";
    } else {
        echo "Значение '$value' равно ", var_export($result, true), "\n";
    }
}


   &example.outputs;


'yes' равно true
'no' равно false
'maybe' не относится к допустимым логическим значениям
